const IconDark = (props: SVGProps<SVGSVGElement>) => <svg xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid" viewBox="0 0 256 256" {...props}><defs><radialGradient id="browserstack-a-dark" cx="50.141%" cy="50.003%" r="50.119%" fx="50.141%" fy="50.003%"><stop offset="0%" stopColor="#797979" /><stop offset="100%" stopColor="#ffffff" /></radialGradient></defs><circle cx={127.949} cy={128.603} r={127.397} fill="#f5bb60" /><circle cx={114.961} cy={115.615} r={114.685} fill="#e86f32" /><circle cx={130.16} cy={100.416} r={99.485} fill="#e53d42" /><circle cx={138.174} cy={108.43} r={91.471} fill="#bfd141" /><circle cx={131.542} cy={115.062} r={84.839} fill="#6db64c" /><circle cx={118.001} cy={101.798} r={71.298} fill="#afdbe7" /><circle cx={129.607} cy={89.915} r={59.691} fill="#57badf" /><circle cx={137.069} cy={97.376} r={52.506} fill="#02b2d6" /><circle cx={129.331} cy={104.837} r={44.768} fill="url(#browserstack-a-dark)" /><circle cx={129.331} cy={104.837} r={44.768} fill="#ffffff" /><path fill="#0a0a0a" d="M141.088 98.971c4.439 1.992 10.56-2.016 13.672-8.951s2.036-14.173-2.402-16.164c-4.44-1.992-10.56 2.016-13.672 8.951s-2.037 14.173 2.402 16.164" /></svg>;

export function BrowserstackLogo({
  variant = "color",
  mode = "auto",
  title = "BrowserStack",
  className,
  ...props
}: BrowserstackLogoProps) {
  const shared = {
    height: "1em",
    ...(title ? { role: "img", "aria-label": title } : { "aria-hidden": true }),
    ...props,
  } as SVGProps<SVGSVGElement>;

  if (variant === "mono") return <IconMono {...shared} className={className} />;

  return mode === "light" ? (
    <Icon {...shared} className={className} />
  ) : mode === "dark" ? (
    <IconDark {...shared} className={className} />
  ) : (
    <>
      <Icon {...shared} className={join(className, "dark:hidden")} />
      <IconDark {...shared} className={join(className, "not-dark:hidden")} />
    </>
  );
}

export default BrowserstackLogo;
